export default function Controls({ conf, setConf, iou, setIou }) {
  return (
    <div>
      <div>
        <label>Confidence: {conf}</label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={conf}
          onChange={(e) => setConf(e.target.value)}
        />
      </div>

      <div>
        <label>IOU: {iou}</label>
        <input
          type="range"
          min="0"
          max="1"
          step="0.01"
          value={iou}
          onChange={(e) => setIou(e.target.value)}
        />
      </div>
    </div>
  );
}