"use client";

import { useState } from "react";
import UploadBox from "../components/UploadBox";
import Controls from "../components/Controls";
import ResultViewer from "../components/ResultViewer";

export default function Home() {
  // ✅ Proper typings
  const [file, setFile] = useState<File | null>(null);
  const [conf, setConf] = useState<number>(0.25);
  const [iou, setIou] = useState<number>(0.45);
  const [imageUrl, setImageUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState<boolean>(false);

  const runPrediction = async () => {
    if (!file) {
      alert("Upload image first");
      return;
    }

    setLoading(true);

    try {
      const formData = new FormData();
      formData.append("file", file);

      const res = await fetch(
        `http://localhost:8000/predict?conf=${conf}&iou=${iou}&return_image=true&save_output=false`,
        {
          method: "POST",
          body: formData,
        }
      );

      if (!res.ok) {
        throw new Error("Prediction failed");
      }

      const blob = await res.blob();
      const url = URL.createObjectURL(blob);

      setImageUrl(url);
    } catch (err) {
      console.error(err);
      alert("Error running prediction");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: 40, fontFamily: "Arial" }}>
      <h1>YOLO Table Detection</h1>

      <UploadBox onFileSelect={setFile} />

      <Controls
        conf={conf}
        setConf={setConf}
        iou={iou}
        setIou={setIou}
      />

      <button onClick={runPrediction} style={{ marginTop: 20 }}>
        {loading ? "Running..." : "Run Detection"}
      </button>

      <ResultViewer imageUrl={imageUrl ?? ""} />
    </div>
  );
}